/**
 * Value Reference system — the foundation of the SDK's type-safe data flow.
 *
 * A Ref<T> is a *description* of a runtime value, not the value itself.
 * It carries enough metadata to serialize into the Elementum API's
 * ValueReferenceInput format (trigger refs, action refs, forEach refs,
 * static values, and template strings).
 *
 * TypeScript sees the phantom T so autocomplete and type checking work;
 * the runtime Proxy layer (see context.ts) constructs these automatically
 * when agent code accesses ctx.trigger.* or ctx.actions.*.
 */
export interface TriggerRefData {
    kind: "trigger";
    name: string;
}
export interface ActionRefData {
    /** Platform wire discriminator; kept as `task` at the serialization boundary. */
    kind: "task";
    actionRefKey: string;
    name: string;
}
export interface ForEachRefData {
    kind: "forEach";
    forEachActionName: string;
    name: string;
}
export interface StaticRefData {
    kind: "static";
    value: unknown;
}
export interface TemplateRefData {
    kind: "template";
    parts: (string | RefData)[];
}
export interface VariableParamRefData {
    kind: "variableParam";
    variableActionRefKey: string;
    name: string;
}
/**
 * A reference to a named secret stored in the Elementum secret vault.
 * Resolved at runtime by the executor; never serialized as plaintext.
 */
export interface SecretRefData {
    kind: "secret";
    secretId: string;
}
export type RefData = TriggerRefData | ActionRefData | ForEachRefData | StaticRefData | TemplateRefData | VariableParamRefData | SecretRefData;
declare const REF_BRAND: unique symbol;
